def transform(grid):
    h, w = len(grid), len(grid[0])
    four = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    six = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    out = [[0 if v == 6 else v for v in row] for row in grid]
    if not four or not six:
        return out
    r0, r1 = min(r for r,c in six), max(r for r,c in six)
    c0, c1 = min(c for r,c in six), max(c for r,c in six)
    fr0, fr1 = min(r for r,c in four), max(r for r,c in four)
    fc0, fc1 = min(c for r,c in four), max(c for r,c in four)
    if c1-c0 > r1-r0:
        # Marker is wider: reflect over the adjacent horizontal seam, toward it.
        if (r0+r1) / 2 >= (fr0+fr1) / 2:
            axis2 = 2*fr1 + 1
        else:
            axis2 = 2*fr0 - 1
        for r,c in four:
            rr = axis2-r
            if 0 <= rr < h:
                out[rr][c] = 4
    else:
        # Vertically oriented marker: reflect across the adjacent vertical seam.
        if (c0+c1) / 2 >= (fc0+fc1) / 2:
            axis2 = 2*fc1 + 1
        else:
            axis2 = 2*fc0 - 1
        for r,c in four:
            cc = axis2-c
            if 0 <= cc < w:
                out[r][cc] = 4
    return out
